import { Component, Element, Host, Prop, h } from "@stencil/core";

/**
 * Semantic typography primitive for consistent text styling.
 *
 * **Usage modes:**
 * 1. Wrap semantic HTML: `<hbr-text variant="page-title"><h1>Title</h1></hbr-text>`
 * 2. Text-only (auto-adds ARIA): `<hbr-text variant="page-title">Title</hbr-text>`
 *
 * **Type determines font family and color:**
 * - heading: heading font, strong color
 * - primary: body font, default color
 * - secondary: body font, medium color
 * - placeholder: body font, weak color
 * - mono: monospace font, default color
 * - number: heading font, strong color (for display numbers)
 */

// Variant definitions - maps semantic names to primitive values
// Based on design system "Heading" typography specs
const VARIANT_PROPS = {
	"page-title": { type: "heading", size: "xl", weight: "bold", ariaLevel: 1 },
	"modal-title": { type: "heading", size: "xl", weight: "bold", ariaLevel: 1 },
	"drawer-title": { type: "heading", size: "xl", weight: "bold", ariaLevel: 2 },
	"section-title": {
		type: "heading",
		size: "lg",
		weight: "bold",
		ariaLevel: 2,
	},
	"sub-section-title": {
		type: "heading",
		size: "md",
		weight: "bold",
		ariaLevel: 3,
	},
	"smallest-title": {
		type: "heading",
		size: "sm",
		weight: "bold",
		ariaLevel: 4,
	},
} as const;

// Map heading sizes to aria-level (for text-only heading mode)
const SIZE_TO_ARIA_LEVEL = {
	xl: 1,
	lg: 2,
	md: 3,
	sm: 4,
	xs: 5,
} as const;

/**
 * @since 2.18.10
 * @status beta
 *
 * @slot - Text content. Can be semantic HTML (h1, h2, p) or plain text.
 *
 * @example
 * // Semantic variant with HTML element
 * <hbr-text variant="page-title"><h1>Dashboard</h1></hbr-text>
 *
 * @example
 * // Text-only mode (auto-adds role="heading" aria-level)
 * <hbr-text variant="section-title">Overview</hbr-text>
 *
 * @example
 * // Primitive props for custom styling
 * <hbr-text type="secondary" size="sm">Metadata</hbr-text>
 *
 * @example
 * // Truncation with line clamping
 * <hbr-text truncate="multiline" lines={3}>Long content...</hbr-text>
 */
@Component({
	tag: "hbr-text",
	styleUrl: "text.scss",
	scoped: false,
})
export class Text {
	@Element() el: HTMLElement;

	/**
	 * Semantic variant bundling type, size, and weight.
	 * Maps to: page-title/modal-title/drawer-title (xl bold), section-title (lg bold),
	 * sub-section-title (md bold), smallest-title (sm bold).
	 */
	@Prop({ reflect: true }) variant:
		| "page-title"
		| "modal-title"
		| "drawer-title"
		| "section-title"
		| "sub-section-title"
		| "smallest-title";

	/** Text role determining font family and color. */
	@Prop() type:
		| "heading"
		| "primary"
		| "secondary"
		| "placeholder"
		| "mono"
		| "number";

	/** Font size from design token scale. */
	@Prop() size: "xs" | "sm" | "md" | "lg" | "xl";

	/** Font weight. */
	@Prop() weight: "normal" | "semibold" | "bold";

	/** Truncation mode: 'end' (ellipsis), 'start' (clip start), 'multiline' (line clamp). */
	@Prop() truncate: "end" | "start" | "multiline";

	/** Number of lines for multiline truncation. Default: 2. */
	@Prop() lines = 2;

	/** Max line length for readability: sm (~60ch), md (~75ch), lg (~90ch). */
	@Prop() length: "sm" | "md" | "lg";

	private hasChildElements(): boolean {
		return Array.from(this.el.childNodes).some(
			(node) => node.nodeType === Node.ELEMENT_NODE,
		);
	}

	componentWillRender() {
		const variantProps = this.variant ? VARIANT_PROPS[this.variant] : null;

		// Priority: explicit prop > variant default > component default
		const finalType = this.type || variantProps?.type || "primary";
		const finalSize = this.size || variantProps?.size || "md";
		const finalWeight = this.weight || variantProps?.weight || "normal";

		// Set CSS variable for multiline truncation via JS (doesn't interfere with user styles)
		if (this.truncate === "multiline") {
			this.el.style.setProperty("--_lines", this.lines.toString());
		} else {
			this.el.style.removeProperty("--_lines");
		}

		// Determine mode: text-only vs with child elements
		const textOnly = !this.hasChildElements();

		// Set core attributes
		this.el.setAttribute("type", finalType);
		this.el.setAttribute("size", finalSize);
		this.el.setAttribute("weight", finalWeight);

		// Set optional attributes
		if (this.truncate) {
			this.el.setAttribute("truncate", this.truncate);
		} else {
			this.el.removeAttribute("truncate");
		}

		if (this.length) {
			this.el.setAttribute("length", this.length);
		} else {
			this.el.removeAttribute("length");
		}

		// Set accessibility attributes for text-only headings
		if (textOnly && finalType === "heading") {
			const ariaLevel =
				variantProps?.ariaLevel ||
				SIZE_TO_ARIA_LEVEL[finalSize as keyof typeof SIZE_TO_ARIA_LEVEL];
			this.el.setAttribute("role", "heading");
			this.el.setAttribute("aria-level", ariaLevel.toString());
		} else {
			this.el.removeAttribute("role");
			this.el.removeAttribute("aria-level");
		}
	}

	render() {
		return <Host />;
	}
}
